@* Rendered by TmNotionTableBlock; shown here to document the contract *@
<TmNotionTableRowBlock Row="@_row"
                       RowIndex="0"
                       ColumnCount="3"
                       ColumnAlignments="@_alignments"
                       IsHeaderRow="true"
                       OnCellsChanged="SaveRowAsync" />

@code {
    // <td> gets tm-notion-table__cell-td--align-center / --align-right
    private TableColumnAlignment[] _alignments =
        [TableColumnAlignment.None, TableColumnAlignment.Center, TableColumnAlignment.Right];
}
